(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-trap-c7-advanced-1"]={"id":"unit22-trap-c7-advanced-1","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"선지 변형 유형 · 정도","name":"심화 5지선다 1","level":"심화","desc":"2-2단원 · 정도","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"정도","parts":[{"name":"U22-06 · 창의적 읽기","items":[{"paragraphCount":1,"readingLabel":"교과서 49쪽 개념 발췌 정리","sourceLabel":"비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리","passage":"[비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리]\n비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다. 내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다. 관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다. 표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다. 비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다. 창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다. 감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-06-S1","type":"mc","sent":"교과서 49쪽 개념 발췌 정리의 내용과 맞는 설명은?","options":["창의적 읽기는 문제를 따져 이해한 뒤, 생각을 바꾸어 새로운 해결 방법을 찾는 읽기다.","창의적 읽기는 글쓴이의 해결 방법만 그대로 따르는 읽기다.","창의적으로 읽을 때는 생각을 바꾸어 볼 필요가 없다.","문제를 이해하지 않아도 창의적으로 읽을 수 있다.","창의적 읽기는 감동만 얻고 문제의 해결 방법은 찾지 않는 읽기다."],"answer":"창의적 읽기는 문제를 따져 이해한 뒤, 생각을 바꾸어 새로운 해결 방법을 찾는 읽기다.","why":"글에 나온 문제를 먼저 이해해요. 그런 다음 생각을 여러 방향으로 바꾸어 보며 새로운 해결 방법을 찾아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","choiceReviews":{"창의적 읽기는 문제를 따져 이해한 뒤, 생각을 바꾸어 새로운 해결 방법을 찾는 읽기다.":{"reason":"글에 나온 문제를 먼저 이해해요. 그런 다음 생각을 여러 방향으로 바꾸어 보며 새로운 해결 방법을 찾아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[]},"창의적 읽기는 글쓴이의 해결 방법만 그대로 따르는 읽기다.":{"reason":"바르게 고치면: 창의적 읽기는 새로운 해결 방법을 찾는 읽기다.\n글에 나온 문제를 먼저 이해해요. 그런 다음 생각을 여러 방향으로 바꾸어 보며 새로운 해결 방법을 찾아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":8,"end":13,"before":"글쓴이의 ","after":"새로운 "},{"start":16,"end":28,"before":"방법만 그대로 따르는 ","after":"방법을 찾는 "}]},"창의적으로 읽을 때는 생각을 바꾸어 볼 필요가 없다.":{"reason":"바르게 고치면: 창의적으로 읽을 때는 생각을 바꾸어 볼 수 있다.\n글에 나온 문제를 먼저 이해해요. 그런 다음 생각을 여러 방향으로 바꾸어 보며 새로운 해결 방법을 찾아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":22,"end":29,"before":"필요가 없다.","after":"수 있다."}]},"문제를 이해하지 않아도 창의적으로 읽을 수 있다.":{"reason":"바르게 고치면: 문제를 따져 이해한 뒤 새로운 해결 방법을 찾아야 한다.\n글에 나온 문제를 먼저 이해해요. 그런 다음 생각을 여러 방향으로 바꾸어 보며 새로운 해결 방법을 찾아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":4,"end":27,"before":"이해하지 않아도 창의적으로 읽을 수 있다.","after":"따져 이해한 뒤 새로운 해결 방법을 찾아야 한다."}]},"창의적 읽기는 감동만 얻고 문제의 해결 방법은 찾지 않는 읽기다.":{"reason":"바르게 고치면: 창의적 읽기는 문제의 새로운 해결 방법을 찾는 읽기다.\n글에 나온 문제를 먼저 이해해요. 그런 다음 생각을 여러 방향으로 바꾸어 보며 새로운 해결 방법을 찾아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":8,"end":15,"before":"감동만 얻고 ","after":""},{"start":15,"end":19,"before":"문제의 ","after":"문제의 새로운 "},{"start":22,"end":32,"before":"방법은 찾지 않는 ","after":"방법을 찾는 "}]}},"pageSpecificReasons":true,"evidence":{"title":"창의적 읽기","statement":"창의적 읽기는 문제를 따져 이해한 뒤, 생각을 바꾸어 새로운 해결 방법을 찾는 읽기다.","explanation":"글에 나온 문제를 먼저 이해해요. 그런 다음 생각을 여러 방향으로 바꾸어 보며 새로운 해결 방법을 찾아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","valid":["D22:6"],"sources":[{"id":"D22","title":"비판적 읽기와 다양한 읽기 방법","label":"교과서 49쪽 개념 발췌 정리","sentences":[{"id":"D22:1","text":"비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다.","paragraph":0,"memberIds":["D22:1"],"topic":"비판적 읽기"},{"id":"D22:2","text":"내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다.","paragraph":0,"memberIds":["D22:2"],"topic":"내용의 타당성"},{"id":"D22:3","text":"관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다.","paragraph":0,"memberIds":["D22:3"],"topic":"관점의 공정성"},{"id":"D22:4","text":"표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다.","paragraph":0,"memberIds":["D22:4"],"topic":"표현 방법의 적절성"},{"id":"D22:5","text":"비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다.","paragraph":0,"memberIds":["D22:5"],"topic":"사회·문화적 이념"},{"id":"D22:6","text":"창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다.","paragraph":0,"memberIds":["D22:6"],"topic":"창의적 읽기"},{"id":"D22:7","text":"감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","paragraph":0,"memberIds":["D22:7"],"topic":"감상적 읽기"}]}]},"editorSourceVersion":"e9725df494a5b73e93efe9ed70aa54d247bf7fd37c877254e39f22054d08be2d"}]},{"name":"U22-07 · 감상적 읽기","items":[{"paragraphCount":1,"readingLabel":"교과서 49쪽 개념 발췌 정리","sourceLabel":"비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리","passage":"[비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리]\n비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다. 내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다. 관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다. 표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다. 비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다. 창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다. 감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-07-S1","type":"mc","sent":"교과서 49쪽 개념 발췌 정리의 내용과 맞는 설명은?","options":["감상적 읽기에서는 모든 독자의 감상이 같아야 한다.","감상적 읽기는 글에 공감하며 감동과 즐거움을 얻는 읽기다. 독자마다 다른 감상을 나눌 수 있다.","감상적 읽기는 글에 공감하지 않고 사실만 확인한다.","감상적 읽기는 글의 사실이 참인지 거짓인지만 판단한다.","다른 독자의 감상을 나누면 글을 이해하는 데 도움이 되지 않는다."],"answer":"감상적 읽기는 글에 공감하며 감동과 즐거움을 얻는 읽기다. 독자마다 다른 감상을 나눌 수 있다.","why":"독자는 글을 읽으며 감동이나 즐거움을 느낄 수 있어요. 같은 글을 읽어도 서로 다르게 느낄 수 있으니 감상을 나누어 보아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","choiceReviews":{"감상적 읽기는 글에 공감하며 감동과 즐거움을 얻는 읽기다. 독자마다 다른 감상을 나눌 수 있다.":{"reason":"독자는 글을 읽으며 감동이나 즐거움을 느낄 수 있어요. 같은 글을 읽어도 서로 다르게 느낄 수 있으니 감상을 나누어 보아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[]},"감상적 읽기에서는 모든 독자의 감상이 같아야 한다.":{"reason":"바르게 고치면: 감상적 읽기에서는 독자마다 다른 감상을 나눌 수 있다.\n독자는 글을 읽으며 감동이나 즐거움을 느낄 수 있어요. 같은 글을 읽어도 서로 다르게 느낄 수 있으니 감상을 나누어 보아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":10,"end":28,"before":"모든 독자의 감상이 같아야 한다.","after":"독자마다 다른 감상을 나눌 수 있다."}]},"감상적 읽기는 글에 공감하지 않고 사실만 확인한다.":{"reason":"바르게 고치면: 감상적 읽기는 글에 공감하며 감동과 즐거움을 얻는다.\n독자는 글을 읽으며 감동이나 즐거움을 느낄 수 있어요. 같은 글을 읽어도 서로 다르게 느낄 수 있으니 감상을 나누어 보아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":11,"end":28,"before":"공감하지 않고 사실만 확인한다.","after":"공감하며 감동과 즐거움을 얻는다."}]},"감상적 읽기는 글의 사실이 참인지 거짓인지만 판단한다.":{"reason":"바르게 고치면: 감상적 읽기는 글에서 감동과 즐거움을 얻는다.\n독자는 글을 읽으며 감동이나 즐거움을 느낄 수 있어요. 같은 글을 읽어도 서로 다르게 느낄 수 있으니 감상을 나누어 보아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":8,"end":30,"before":"글의 사실이 참인지 거짓인지만 판단한다.","after":"글에서 감동과 즐거움을 얻는다."}]},"다른 독자의 감상을 나누면 글을 이해하는 데 도움이 되지 않는다.":{"reason":"바르게 고치면: 다른 독자의 감상을 나누면 글을 이해하는 데 도움이 될 수 있다.\n독자는 글을 읽으며 감동이나 즐거움을 느낄 수 있어요. 같은 글을 읽어도 서로 다르게 느낄 수 있으니 감상을 나누어 보아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":29,"end":36,"before":"되지 않는다.","after":"될 수 있다."}]}},"pageSpecificReasons":true,"evidence":{"title":"감상적 읽기","statement":"감상적 읽기는 글에 공감하며 감동과 즐거움을 얻는 읽기다. 독자마다 다른 감상을 나눌 수 있다.","explanation":"독자는 글을 읽으며 감동이나 즐거움을 느낄 수 있어요. 같은 글을 읽어도 서로 다르게 느낄 수 있으니 감상을 나누어 보아요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","valid":["D22:7"],"sources":[{"id":"D22","title":"비판적 읽기와 다양한 읽기 방법","label":"교과서 49쪽 개념 발췌 정리","sentences":[{"id":"D22:1","text":"비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다.","paragraph":0,"memberIds":["D22:1"],"topic":"비판적 읽기"},{"id":"D22:2","text":"내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다.","paragraph":0,"memberIds":["D22:2"],"topic":"내용의 타당성"},{"id":"D22:3","text":"관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다.","paragraph":0,"memberIds":["D22:3"],"topic":"관점의 공정성"},{"id":"D22:4","text":"표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다.","paragraph":0,"memberIds":["D22:4"],"topic":"표현 방법의 적절성"},{"id":"D22:5","text":"비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다.","paragraph":0,"memberIds":["D22:5"],"topic":"사회·문화적 이념"},{"id":"D22:6","text":"창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다.","paragraph":0,"memberIds":["D22:6"],"topic":"창의적 읽기"},{"id":"D22:7","text":"감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","paragraph":0,"memberIds":["D22:7"],"topic":"감상적 읽기"}]}]},"editorSourceVersion":"5c7ee766d382b99bd057b0af89dcebc4530162ec5e752431635a1fbca7cab80f"}]},{"name":"U22-21 · 경제적 효율성의 정의","items":[{"paragraphCount":1,"readingLabel":"7문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 7문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 7문단]\n미국에서 가장 널리 쓰이는 경제학 교과서 중 한 권을 저술한 경제학자 그레고리 맨큐(Gregory Mankiw)는 암표 판매를 예로 들어 자유 시장의 미덕을 설명한다. 경제적 효율성이란 사회 구성원 전체의 경제적 행복을 극대화하는 방식으로 재화를 분배하는 것이다. 맨큐는 자유 시장이 얼마만큼의 돈을 지불할 의사가 있느냐를 기준으로 재화의 가치를 가장 높게 평가하는 구매자에게 재화를 공급함으로써 이러한 목적에 기여한다고 주장한다. 그는 암표 거래 현상을 예로 들면서 이렇게 말했다. “부족한 자원을 효율적으로 분배하려면, 재화는 그 가치를 가장 높게 평가하는 소비자에게 돌아가야 한다. 암표 거래가 바로 시장이 효율적 결론에 도달하는 방식을 나타내는 예다. …… 암표상은 표에 시장이 감당할 수 있는 최고 가격을 매김으로써, 가장 높은 가격을 지불할 의사가 있는 소비자가 실제로 표를 손에 넣을 수 있도록 보장한다.”","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-21-S1","type":"mc","sent":"7문단의 내용과 맞는 설명은?","options":["경제적 효율성은 물건이나 서비스를 나누어 사회 전체의 경제적 이익과 만족을 최대한 늘리는 것이다.","경제적 효율성은 파는 사람의 이익과 만족만 늘리는 것이다.","경제적 효율성은 사회 전체의 이익과 만족을 최대한 줄이는 것이다.","물건을 나누어 사회 전체의 경제적 이익을 최대한 늘리는 것을 '비효율성'이라고 한다.","관람료 수입만 늘어나면 사회 전체의 경제적 이익은 살필 필요가 없다."],"answer":"경제적 효율성은 물건이나 서비스를 나누어 사회 전체의 경제적 이익과 만족을 최대한 늘리는 것이다.","why":"경제적 효율성을 따질 때는 한 사람의 이익만 보지 않아요. 사회 전체가 얻는 경제적 이익과 만족을 모두 더해 얼마나 커지는지 살펴요.\n7문단에서 확인할 수 있어요.","choiceReviews":{"경제적 효율성은 물건이나 서비스를 나누어 사회 전체의 경제적 이익과 만족을 최대한 늘리는 것이다.":{"reason":"경제적 효율성을 따질 때는 한 사람의 이익만 보지 않아요. 사회 전체가 얻는 경제적 이익과 만족을 모두 더해 얼마나 커지는지 살펴요.\n7문단에서 확인할 수 있어요.","edits":[]},"경제적 효율성은 파는 사람의 이익과 만족만 늘리는 것이다.":{"reason":"바르게 고치면: 경제적 효율성은 사회 전체의 경제적 이익과 만족을 늘리는 것이다.\n경제적 효율성을 따질 때는 한 사람의 이익만 보지 않아요. 사회 전체가 얻는 경제적 이익과 만족을 모두 더해 얼마나 커지는지 살펴요.\n7문단에서 확인할 수 있어요.","edits":[{"start":9,"end":16,"before":"파는 사람의 ","after":"사회 전체의 경제적 "},{"start":20,"end":24,"before":"만족만 ","after":"만족을 "}]},"경제적 효율성은 사회 전체의 이익과 만족을 최대한 줄이는 것이다.":{"reason":"바르게 고치면: 경제적 효율성은 사회 전체의 이익과 만족을 최대한 늘리는 것이다.\n경제적 효율성을 따질 때는 한 사람의 이익만 보지 않아요. 사회 전체가 얻는 경제적 이익과 만족을 모두 더해 얼마나 커지는지 살펴요.\n7문단에서 확인할 수 있어요.","edits":[{"start":28,"end":32,"before":"줄이는 ","after":"늘리는 "}]},"물건을 나누어 사회 전체의 경제적 이익을 최대한 늘리는 것을 '비효율성'이라고 한다.":{"reason":"바르게 고치면: 물건을 나누어 사회 전체의 경제적 이익을 최대한 늘리는 것을 '효율성'이라고 한다.\n경제적 효율성을 따질 때는 한 사람의 이익만 보지 않아요. 사회 전체가 얻는 경제적 이익과 만족을 모두 더해 얼마나 커지는지 살펴요.\n7문단에서 확인할 수 있어요.","edits":[{"start":34,"end":44,"before":"'비효율성'이라고 ","after":"'효율성'이라고 "}]},"관람료 수입만 늘어나면 사회 전체의 경제적 이익은 살필 필요가 없다.":{"reason":"바르게 고치면: 사회 전체의 경제적 이익과 만족이 커지는지 살펴야 한다.\n경제적 효율성을 따질 때는 한 사람의 이익만 보지 않아요. 사회 전체가 얻는 경제적 이익과 만족을 모두 더해 얼마나 커지는지 살펴요.\n7문단에서 확인할 수 있어요.","edits":[{"start":0,"end":13,"before":"관람료 수입만 늘어나면 ","after":""},{"start":24,"end":38,"before":"이익은 살필 필요가 없다.","after":"이익과 만족이 커지는지 살펴야 한다."}]}},"pageSpecificReasons":true,"evidence":{"title":"경제적 효율성의 정의","statement":"경제적 효율성은 물건이나 서비스를 나누어 사회 전체의 경제적 이익과 만족을 최대한 늘리는 것이다.","explanation":"경제적 효율성을 따질 때는 한 사람의 이익만 보지 않아요. 사회 전체가 얻는 경제적 이익과 만족을 모두 더해 얼마나 커지는지 살펴요.\n7문단에서 확인할 수 있어요.","valid":["L07:2"],"sources":[{"id":"L07","title":"줄 서기를 돈으로 살 수 있을까","label":"7문단","sentences":[{"id":"L07:1","text":"미국에서 가장 널리 쓰이는 경제학 교과서 중 한 권을 저술한 경제학자 그레고리 맨큐(Gregory Mankiw)는 암표 판매를 예로 들어 자유 시장의 미덕을 설명한다.","paragraph":0,"memberIds":["L07:1"],"topic":"맨큐는 미국에서 가장 널리 쓰이는 경제학 교과서 중 하나를 쓴 경제학자다. 그는 암표를 예로 들어 시장의 좋은 점(미덕)을 설명한다."},{"id":"L07:2","text":"경제적 효율성이란 사회 구성원 전체의 경제적 행복을 극대화하는 방식으로 재화를 분배하는 것이다.","paragraph":0,"memberIds":["L07:2"],"topic":"'경제적 효율성'이란 사회 모든 사람의 경제적 행복이 가장 커지도록 물건을 나누는 것이다."},{"id":"L07:3","text":"맨큐는 자유 시장이 얼마만큼의 돈을 지불할 의사가 있느냐를 기준으로 재화의 가치를 가장 높게 평가하는 구매자에게 재화를 공급함으로써 이러한 목적에 기여한다고 주장한다.","paragraph":0,"memberIds":["L07:3"],"topic":"시장은 '얼마 낼 마음이 있나'를 기준으로 삼는다. 그 기준으로 물건을 가장 귀하게 여기는 사람에게 준다. 그래서 시장은 모두의 행복을 키우는 데(효율성) 도움이 된다. 맨큐는 이렇게 주장한다."},{"id":"L07:4","text":"그는 암표 거래 현상을 예로 들면서 이렇게 말했다.","paragraph":0,"memberIds":["L07:4"],"topic":"그는 암표를 예로 들어 이렇게 말했다."},{"id":"L07:5","text":"“부족한 자원을 효율적으로 분배하려면, 재화는 그 가치를 가장 높게 평가하는 소비자에게 돌아가야 한다. 암표 거래가 바로 시장이 효율적 결론에 도달하는 방식을 나타내는 예다. …… 암표상은 표에 시장이 감당할 수 있는 최고 가격을 매김으로써, 가장 높은 가격을 지불할 의사가 있는 소비자가 실제로 표를 손에 넣을 수 있도록 보장한다.”","paragraph":0,"memberIds":["L07:5","L07:6","L07:7"],"topic":"\"물건이 모자랄 때 잘 나누려면, 그 물건을 가장 귀하게 여기는 사람이 가져야 한다."}]}]},"editorSourceVersion":"4c3d55ff5c1418da8927105e17d806a9deaa49e4814207f5630e8dcb3fd1e8ce"}]},{"name":"U22-26 · 공정성 주장에 대한 필자의 평가","items":[{"paragraphCount":1,"readingLabel":"10문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 10문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 10문단]\n아마도 대변인의 의도는 암표 거래는 125달러를 지불할 만한 경제적 여유가 없는 사람에게 불공정한 행위라는 것이리라. 보통 사람은 그만큼 불리하게 되어 입장권을 손에 넣기가 더욱 힘들어진다. 이 주장은 설득력이 있다. 돈을 받고 대신 줄을 선 사람이나 암표상이 입장권을 확보했다면 그 뒤에 서 있던 사람, 즉 암표 가격을 지불할 만한 경제적 여유가 없는 사람은 손해를 본다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-26-S1","type":"mc","sent":"10문단의 내용과 맞는 설명은?","options":["글쓴이는 대변인의 말을 돈 없는 관객이 불리해진다는 뜻으로 이해한다. 글쓴이도 그 걱정이 설득력 있다고 본다.","글쓴이는 돈 없는 관객이 불리해진다는 말에 설득력이 없다고 본다.","글쓴이는 대변인이 암표가 돈 없는 관객에게 공정하다고 말한 것으로 이해한다.","글쓴이는 대변인이 가장 비싼 값을 내는 관객을 걱정했다고 이해한다.","'돈이 없는 사람에게 불공정하다'는 말은 대변인이 직접 한 말이다."],"answer":"글쓴이는 대변인의 말을 돈 없는 관객이 불리해진다는 뜻으로 이해한다. 글쓴이도 그 걱정이 설득력 있다고 본다.","why":"필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","choiceReviews":{"글쓴이는 대변인의 말을 돈 없는 관객이 불리해진다는 뜻으로 이해한다. 글쓴이도 그 걱정이 설득력 있다고 본다.":{"reason":"필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[]},"글쓴이는 돈 없는 관객이 불리해진다는 말에 설득력이 없다고 본다.":{"reason":"바르게 고치면: 글쓴이는 돈 없는 관객이 불리해진다는 말에 설득력이 있다고 본다.\n필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[{"start":29,"end":33,"before":"없다고 ","after":"있다고 "}]},"글쓴이는 대변인이 암표가 돈 없는 관객에게 공정하다고 말한 것으로 이해한다.":{"reason":"바르게 고치면: 글쓴이는 대변인이 암표가 돈 없는 관객에게 불공정하다고 말한 것으로 이해한다.\n필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[{"start":24,"end":30,"before":"공정하다고 ","after":"불공정하다고 "}]},"글쓴이는 대변인이 가장 비싼 값을 내는 관객을 걱정했다고 이해한다.":{"reason":"바르게 고치면: 글쓴이는 대변인이 돈이 부족한 관객을 걱정했다고 이해한다.\n필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[{"start":10,"end":22,"before":"가장 비싼 값을 내는 ","after":"돈이 부족한 "}]},"'돈이 없는 사람에게 불공정하다'는 말은 대변인이 직접 한 말이다.":{"reason":"바르게 고치면: '돈이 없는 사람에게 불공정하다'는 말은 글쓴이가 대변인의 말을 풀어서 설명한 것이다.\n필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","edits":[{"start":23,"end":37,"before":"대변인이 직접 한 말이다.","after":"글쓴이가 대변인의 말을 풀어서 설명한 것이다."}]}},"pageSpecificReasons":true,"evidence":{"title":"공정성 주장에 대한 필자의 평가","statement":"글쓴이는 대변인의 말을 돈 없는 관객이 불리해진다는 뜻으로 이해한다. 글쓴이도 그 걱정이 설득력 있다고 본다.","explanation":"필자는 “아마도 … 것이리라”라고 하며 대변인의 의도를 짐작해요. “이 주장”은 돈이 부족한 사람에게 암표 거래가 불공정하다는 뜻이고, 필자는 이에 설득력이 있다고 평가해요.\n10문단에서 확인할 수 있어요.","valid":["L10:3"],"sources":[{"id":"L10","title":"줄 서기를 돈으로 살 수 있을까","label":"10문단","sentences":[{"id":"L10:1","text":"아마도 대변인의 의도는 암표 거래는 125달러를 지불할 만한 경제적 여유가 없는 사람에게 불공정한 행위라는 것이리라.","paragraph":0,"memberIds":["L10:1"],"topic":"대변인이 하고 싶은 말은 아마 이것일 것이다. \"암표는 125달러를 낼 돈이 없는 사람에게 불공평하다.\""},{"id":"L10:2","text":"보통 사람은 그만큼 불리하게 되어 입장권을 손에 넣기가 더욱 힘들어진다.","paragraph":0,"memberIds":["L10:2"],"topic":"평범한 사람은 그만큼 불리해져서 표를 구하기가 더 어려워진다."},{"id":"L10:3","text":"이 주장은 설득력이 있다.","paragraph":0,"memberIds":["L10:3"],"topic":"필자는 “암표 거래는 돈이 부족한 사람에게 불공정하다”는 주장에 설득력이 있다고 본다."},{"id":"L10:4","text":"돈을 받고 대신 줄을 선 사람이나 암표상이 입장권을 확보했다면 그 뒤에 서 있던 사람, 즉 암표 가격을 지불할 만한 경제적 여유가 없는 사람은 손해를 본다.","paragraph":0,"memberIds":["L10:4"],"topic":"줄 알바나 암표상이 앞에서 표를 가져가 버리면, 그 뒤에 선 사람은 표를 못 받는다. 그 사람은 비싼 암표를 살 돈도 없다. 그러니 손해를 본다."}]}]},"editorSourceVersion":"fef777d1ab3a5986f8fc143e00fc66ae18de606344a5249c078b8295f55cac74"}]},{"name":"U22-30 · 지불 의사와 가치 평가의 불일치","items":[{"paragraphCount":1,"readingLabel":"12문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 12문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 12문단]\n하지만 이러한 주장은 설득력이 없다. 우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다. 어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다. 시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다. 셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다. 그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-30-S1","type":"mc","sent":"12문단의 내용과 맞는 설명은?","options":["글쓴이는 돈을 더 내겠다는 사람이 반드시 물건을 더 소중히 여긴다고 본다.","사회 전체의 이익을 늘리려면 돈을 받고 파는 방법이 줄을 세우는 방법보다 반드시 더 낫다.","사회 전체의 이익을 늘리려면 시장이 더 나은지 따져 볼 필요가 없다.","'기꺼이 돈을 낸다'는 말은 돈을 내고 싶은 마음과 상관없는 말이다.","돈을 더 내겠다는 사람이 물건을 더 소중히 여긴다고 할 수는 없다. 글쓴이는 돈을 받고 파는 방법이 줄을 세우는 방법보다 항상 더 낫다고 보지 않는다."],"answer":"돈을 더 내겠다는 사람이 물건을 더 소중히 여긴다고 할 수는 없다. 글쓴이는 돈을 받고 파는 방법이 줄을 세우는 방법보다 항상 더 낫다고 보지 않는다.","why":"“하지만 이러한 주장은”은 바로 앞에서 소개한 시장 옹호자 반론을 가리켜요. 필자는 돈을 많이 내겠다고 해서 공연을 가장 원한다고 볼 수는 없다고 반박해요. 보고 싶은 마음이 커도 돈이 부족할 수 있기 때문이에요.\n12문단에서 확인할 수 있어요.","choiceReviews":{"돈을 더 내겠다는 사람이 물건을 더 소중히 여긴다고 할 수는 없다. 글쓴이는 돈을 받고 파는 방법이 줄을 세우는 방법보다 항상 더 낫다고 보지 않는다.":{"reason":"“하지만 이러한 주장은”은 바로 앞에서 소개한 시장 옹호자 반론을 가리켜요. 필자는 돈을 많이 내겠다고 해서 공연을 가장 원한다고 볼 수는 없다고 반박해요. 보고 싶은 마음이 커도 돈이 부족할 수 있기 때문이에요.\n12문단에서 확인할 수 있어요.","edits":[]},"글쓴이는 돈을 더 내겠다는 사람이 반드시 물건을 더 소중히 여긴다고 본다.":{"reason":"바르게 고치면: 글쓴이는 돈을 더 내겠다는 사람이 물건을 더 소중히 여긴다고 할 수는 없다고 본다.\n“하지만 이러한 주장은”은 바로 앞에서 소개한 시장 옹호자 반론을 가리켜요. 필자는 돈을 많이 내겠다고 해서 공연을 가장 원한다고 볼 수는 없다고 반박해요. 보고 싶은 마음이 커도 돈이 부족할 수 있기 때문이에요.\n12문단에서 확인할 수 있어요.","edits":[{"start":19,"end":23,"before":"반드시 ","after":""},{"start":33,"end":38,"before":"여긴다고 ","after":"여긴다고 할 수는 없다고 "}]},"사회 전체의 이익을 늘리려면 돈을 받고 파는 방법이 줄을 세우는 방법보다 반드시 더 낫다.":{"reason":"바르게 고치면: 사회 전체의 이익을 늘리려 해도 돈을 받고 파는 방법이 줄을 세우는 방법보다 더 낫다고 단정할 수는 없다.\n“하지만 이러한 주장은”은 바로 앞에서 소개한 시장 옹호자 반론을 가리켜요. 필자는 돈을 많이 내겠다고 해서 공연을 가장 원한다고 볼 수는 없다고 반박해요. 보고 싶은 마음이 커도 돈이 부족할 수 있기 때문이에요.\n12문단에서 확인할 수 있어요.","edits":[{"start":11,"end":16,"before":"늘리려면 ","after":"늘리려 해도 "},{"start":41,"end":45,"before":"반드시 ","after":""},{"start":47,"end":50,"before":"낫다.","after":"낫다고 단정할 수는 없다."}]},"사회 전체의 이익을 늘리려면 시장이 더 나은지 따져 볼 필요가 없다.":{"reason":"바르게 고치면: 사회 전체의 이익을 늘리려 해도 시장이 더 나은지 따져 보아야 한다.\n“하지만 이러한 주장은”은 바로 앞에서 소개한 시장 옹호자 반론을 가리켜요. 필자는 돈을 많이 내겠다고 해서 공연을 가장 원한다고 볼 수는 없다고 반박해요. 보고 싶은 마음이 커도 돈이 부족할 수 있기 때문이에요.\n12문단에서 확인할 수 있어요.","edits":[{"start":11,"end":16,"before":"늘리려면 ","after":"늘리려 해도 "},{"start":29,"end":38,"before":"볼 필요가 없다.","after":"보아야 한다."}]},"'기꺼이 돈을 낸다'는 말은 돈을 내고 싶은 마음과 상관없는 말이다.":{"reason":"바르게 고치면: '기꺼이 돈을 낸다'는 말은 스스로 돈을 낼 마음이 있다는 말이다.\n“하지만 이러한 주장은”은 바로 앞에서 소개한 시장 옹호자 반론을 가리켜요. 필자는 돈을 많이 내겠다고 해서 공연을 가장 원한다고 볼 수는 없다고 반박해요. 보고 싶은 마음이 커도 돈이 부족할 수 있기 때문이에요.\n12문단에서 확인할 수 있어요.","edits":[{"start":13,"end":16,"before":"말은 ","after":"말은 스스로 "},{"start":19,"end":34,"before":"내고 싶은 마음과 상관없는 ","after":"낼 마음이 있다는 "}]}},"pageSpecificReasons":true,"evidence":{"title":"지불 의사와 가치 평가의 불일치","statement":"돈을 더 내겠다는 사람이 물건을 더 소중히 여긴다고 할 수는 없다. 글쓴이는 돈을 받고 파는 방법이 줄을 세우는 방법보다 항상 더 낫다고 보지 않는다.","explanation":"“하지만 이러한 주장은”은 바로 앞에서 소개한 시장 옹호자 반론을 가리켜요. 필자는 돈을 많이 내겠다고 해서 공연을 가장 원한다고 볼 수는 없다고 반박해요. 보고 싶은 마음이 커도 돈이 부족할 수 있기 때문이에요.\n12문단에서 확인할 수 있어요.","valid":["L12:2","L12:3"],"sources":[{"id":"L12","title":"줄 서기를 돈으로 살 수 있을까","label":"12문단","sentences":[{"id":"L12:1","text":"하지만 이러한 주장은 설득력이 없다.","paragraph":0,"memberIds":["L12:1"],"topic":"필자는 11문단에서 예상한 시장 옹호자의 반론, 곧 “비싼 값을 내는 사람이 공연을 가장 원하므로 시장에 맡기자”는 주장에 설득력이 없다고 본다."},{"id":"L12:2","text":"우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다.","paragraph":0,"memberIds":["L12:2"],"topic":"목표가 '모두의 만족을 최대로'라고 쳐도, 시장이 줄 서기보다 더 믿을 만하지 않을 수도 있다."},{"id":"L12:3","text":"어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다.","paragraph":0,"memberIds":["L12:3"],"topic":"돈을 많이 낸다고 해서 꼭 그걸 더 좋아한다는 뜻은 아니기 때문이다."},{"id":"L12:4","text":"시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다.","paragraph":0,"memberIds":["L12:4"],"topic":"가격에는 '얼마나 사고 싶은지(마음)'뿐 아니라 '돈이 얼마나 있는지(능력)'도 들어 있다."},{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.","paragraph":0,"memberIds":["L12:5"],"topic":"공연이나 경기를 가장 보고 싶은 사람도 표 살 돈이 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","paragraph":0,"memberIds":["L12:6"],"topic":"반대로, 가장 비싼 표를 산 사람이 그 공연을 별로 좋아하지 않을 수도 있다."}]}]},"editorSourceVersion":"3681797208c659f46221987a53e0f2ff1cbe9161aeb76ddb2e616cf20c2ad78b"}]},{"name":"U22-32 · 간절함과 구매력의 엇갈림","items":[{"paragraphCount":1,"readingLabel":"12문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 12문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 12문단]\n하지만 이러한 주장은 설득력이 없다. 우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다. 어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다. 시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다. 셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다. 그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-32-S1","type":"mc","sent":"12문단의 내용과 맞는 설명은?","options":["공연을 꼭 보고 싶은 관객은 누구나 표를 살 돈이 충분하다.","공연을 꼭 보고 싶어도 표를 살 돈이 없을 수 있다. 비싼 표를 산 사람도 공연에 별 관심이 없을 수 있다.","가장 비싼 표를 산 사람은 반드시 공연을 가장 소중히 여긴다.","표를 살 돈이 없는 사람은 공연을 꼭 보고 싶은 마음도 없다.","가장 비싼 값을 낸 사람은 언제나 공연을 가장 보고 싶어 한 사람이다."],"answer":"공연을 꼭 보고 싶어도 표를 살 돈이 없을 수 있다. 비싼 표를 산 사람도 공연에 별 관심이 없을 수 있다.","why":"돈이 부족하다고 공연을 좋아하는 마음까지 작은 것은 아니에요. 반대로 돈이 많으면 공연을 별로 좋아하지 않아도 비싼 표를 살 수 있어요.\n12문단에서 확인할 수 있어요.","choiceReviews":{"공연을 꼭 보고 싶어도 표를 살 돈이 없을 수 있다. 비싼 표를 산 사람도 공연에 별 관심이 없을 수 있다.":{"reason":"돈이 부족하다고 공연을 좋아하는 마음까지 작은 것은 아니에요. 반대로 돈이 많으면 공연을 별로 좋아하지 않아도 비싼 표를 살 수 있어요.\n12문단에서 확인할 수 있어요.","edits":[]},"공연을 꼭 보고 싶은 관객은 누구나 표를 살 돈이 충분하다.":{"reason":"바르게 고치면: 공연을 꼭 보고 싶은 관객도 표를 살 돈이 부족할 수 있다.\n돈이 부족하다고 공연을 좋아하는 마음까지 작은 것은 아니에요. 반대로 돈이 많으면 공연을 별로 좋아하지 않아도 비싼 표를 살 수 있어요.\n12문단에서 확인할 수 있어요.","edits":[{"start":12,"end":20,"before":"관객은 누구나 ","after":"관객도 "},{"start":28,"end":33,"before":"충분하다.","after":"부족할 수 있다."}]},"가장 비싼 표를 산 사람은 반드시 공연을 가장 소중히 여긴다.":{"reason":"바르게 고치면: 가장 비싼 표를 산 사람도 공연을 별로 소중히 여기지 않을 수 있다.\n돈이 부족하다고 공연을 좋아하는 마음까지 작은 것은 아니에요. 반대로 돈이 많으면 공연을 별로 좋아하지 않아도 비싼 표를 살 수 있어요.\n12문단에서 확인할 수 있어요.","edits":[{"start":11,"end":19,"before":"사람은 반드시 ","after":"사람도 "},{"start":23,"end":26,"before":"가장 ","after":"별로 "},{"start":30,"end":34,"before":"여긴다.","after":"여기지 않을 수 있다."}]},"표를 살 돈이 없는 사람은 공연을 꼭 보고 싶은 마음도 없다.":{"reason":"바르게 고치면: 표를 살 돈이 없는 사람도 공연을 꼭 보고 싶은 마음은 있을 수 있다.\n돈이 부족하다고 공연을 좋아하는 마음까지 작은 것은 아니에요. 반대로 돈이 많으면 공연을 별로 좋아하지 않아도 비싼 표를 살 수 있어요.\n12문단에서 확인할 수 있어요.","edits":[{"start":11,"end":15,"before":"사람은 ","after":"사람도 "},{"start":27,"end":34,"before":"마음도 없다.","after":"마음은 있을 수 있다."}]},"가장 비싼 값을 낸 사람은 언제나 공연을 가장 보고 싶어 한 사람이다.":{"reason":"바르게 고치면: 가장 비싼 값을 낸 사람이 언제나 공연을 가장 보고 싶어 한 사람인 것은 아니다.\n돈이 부족하다고 공연을 좋아하는 마음까지 작은 것은 아니에요. 반대로 돈이 많으면 공연을 별로 좋아하지 않아도 비싼 표를 살 수 있어요.\n12문단에서 확인할 수 있어요.","edits":[{"start":11,"end":15,"before":"사람은 ","after":"사람이 "},{"start":34,"end":39,"before":"사람이다.","after":"사람인 것은 아니다."}]}},"pageSpecificReasons":true,"evidence":{"title":"간절함과 구매력의 엇갈림","statement":"공연을 꼭 보고 싶어도 표를 살 돈이 없을 수 있다. 비싼 표를 산 사람도 공연에 별 관심이 없을 수 있다.","explanation":"돈이 부족하다고 공연을 좋아하는 마음까지 작은 것은 아니에요. 반대로 돈이 많으면 공연을 별로 좋아하지 않아도 비싼 표를 살 수 있어요.\n12문단에서 확인할 수 있어요.","valid":["L12:5","L12:6"],"sources":[{"id":"L12","title":"줄 서기를 돈으로 살 수 있을까","label":"12문단","sentences":[{"id":"L12:1","text":"하지만 이러한 주장은 설득력이 없다.","paragraph":0,"memberIds":["L12:1"],"topic":"필자는 11문단에서 예상한 시장 옹호자의 반론, 곧 “비싼 값을 내는 사람이 공연을 가장 원하므로 시장에 맡기자”는 주장에 설득력이 없다고 본다."},{"id":"L12:2","text":"우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다.","paragraph":0,"memberIds":["L12:2"],"topic":"목표가 '모두의 만족을 최대로'라고 쳐도, 시장이 줄 서기보다 더 믿을 만하지 않을 수도 있다."},{"id":"L12:3","text":"어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다.","paragraph":0,"memberIds":["L12:3"],"topic":"돈을 많이 낸다고 해서 꼭 그걸 더 좋아한다는 뜻은 아니기 때문이다."},{"id":"L12:4","text":"시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다.","paragraph":0,"memberIds":["L12:4"],"topic":"가격에는 '얼마나 사고 싶은지(마음)'뿐 아니라 '돈이 얼마나 있는지(능력)'도 들어 있다."},{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.","paragraph":0,"memberIds":["L12:5"],"topic":"공연이나 경기를 가장 보고 싶은 사람도 표 살 돈이 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","paragraph":0,"memberIds":["L12:6"],"topic":"반대로, 가장 비싼 표를 산 사람이 그 공연을 별로 좋아하지 않을 수도 있다."}]}]},"editorSourceVersion":"4c4d3ada8c397c774daf42a33196556b6446ef2bcac20a231f8a44541d192553"}]}]};})(window);
